 const auto original=a;const int reps=(mode==1||mode==2||mode==3?8:1)*std::max(std::size_t{1},std::size_t{131072}/std::max(std::size_t{1},n));std::uint64_t checksum=0;
 auto run=[&]<bool Strict>(){
