#endif
 };auto t=std::clock();std::atomic_signal_fence(std::memory_order_seq_cst);for(int i=0;i<reps;++i){run.template operator()<(STRICT_MODE != 0)>();}std::atomic_signal_fence(std::memory_order_seq_cst);auto elapsed=std::clock()-t;if(a!=original)return 3;std::printf("%ju %ju\n",std::uintmax_t(elapsed)*1000000000/CLOCKS_PER_SEC,std::uintmax_t(checksum));}

