        const auto m2 = std::size_t{0} - static_cast<std::size_t>(b2);
        lo += ((quarter + 1) & m0) + (quarter & m1) + (quarter & m2);
        count = quarter - static_cast<std::size_t>(b0) + ((count % 4) & m2);
