                    const auto m0 = std::size_t{0} - static_cast<std::size_t>(b0);
                    const auto m1 = std::size_t{0} - static_cast<std::size_t>(b1);
                    const auto m2 = std::size_t{0} - static_cast<std::size_t>(b2);
