            previous[i] = tails.back();
            if (values.size() == values.capacity()) {
                const auto capacity = values.capacity();
                values.reserve(capacity + std::min(capacity, v.size() - capacity));
            }
            if (values.size() == values.capacity()) std::unreachable();
